import logging
import time
from os import path

from ute_ue.config import loggers as ta_ue_logging
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments, DataTransferVerificationFailure


class AndroidDataTransferFtp(LteDataTransfer):
    """Object responsible for managing Android data transfer."""
    # pylint: disable = protected-access, too-many-instance-attributes, duplicate-code

    def __init__(self, name, dt_definition, configuration, android_ue, logger_name='ute_ue'):
        """
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param android_ue:
        """
        super(AndroidDataTransferFtp, self).__init__(name, dt_definition, configuration, logger_name)
        raw_logger = logging.getLogger('ute_ue')
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.android_ue = android_ue
        self.success_started = False
        self.ftp_ip = self._get_ftp_parameter('host_ip')
        self.ftp_user = self._get_ftp_parameter('user')
        self.ftp_pass = self._get_ftp_parameter('password')
        self.ftp_remote_path = self._get_ftp_parameter('remote_path')
        self.ue_local_path = self._get_ftp_parameter('local_path')
        self.pid = None
        self.cmd = None

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        try:
            self.cmd, self.pid = self.android_ue._method_proxy('start_ftp_data_transfer', self._dt_definition.direction,
                                                               self.ue_local_path, self.ftp_remote_path, self.ftp_ip,
                                                               self.ftp_user, self.ftp_pass)
        except Exception as e:
            self.release_data_transfer()
            self.logger.debug('Something went wrong during {} ftp data transfer start:\n{}'.format(self.name, e))
            raise e

        self._ensure_started()

    def _ensure_started(self, timeout=15):
        end_time = time.time() + timeout
        while time.time() < end_time:
            pid = self.pid
            if pid is not None:
                self.logger.info('{} FTP data transfer started on UE, cmd: {} , pid: {}'.format(self.name, self.cmd,
                                                                                                self.pid))
                self.success_started = True
                break
            time.sleep(1)

        if not self.success_started:
            raise Exception('Failed to start ftp data transfer within specified amount of time: {}s'.format(timeout))

    def stop(self):
        """Stops ongoing data transfer"""
        if self.is_running():
            self.android_ue._method_proxy('stop_ftp_data_transfer', self.pid)
        else:
            self.logger.debug('Data transfer {} is not running. No need to stop it'.format(self.name))

    def await_finish(self):
        """Waits until this data transfer finish."""
        while True:
            is_finished = self.android_ue._method_proxy('is_process_finished', self.pid)
            if is_finished:
                self.pid = None
                break
            time.sleep(1)
            self.logger.debug('Data transfer process with PID {} is still running.'.format(self.pid))

    def _get_ftp_parameter(self, param):
        config = self._configuration
        if param in self._dt_definition.protocol_details:
            return self._dt_definition.protocol_details[param]
        if 'ftp' in config['data_transfer'] and param in config['data_transfer']['ftp']:
            return config['data_transfer']['ftp'][param]
        return self._raise_if_direction_required_param_missing(param)

    def _raise_if_direction_required_param_missing(self, param):
        direction_required_params = {'dl': ['host_ip', 'remote_path', 'local_path'],
                                     'ul': ['host_ip', 'remote_path', 'local_path', 'user', 'password']}
        if param in direction_required_params[self._dt_definition.direction]:
            err_msg = "Please provide {} argument at the end of keyword or in ftp section at yml file.".format(param)
            raise DataTransferMissingArguments(err_msg)

    def _is_upload(self):
        return self._dt_definition.direction == 'ul'

    def release_data_transfer(self):
        """FTP data transfer cleanup"""
        if not self.is_running():
            self.logger.debug('Data transfer {} has finished. No need to release again'.format(self.name))
            return

        if self._is_upload():
            filename = path.basename(self.ue_local_path)
            ftp_file_path = '{}/{}'.format(self.ftp_remote_path, filename)
            self.android_ue._method_proxy('release_uplink_ftp_data_transfer', self.pid, self.ftp_ip, self.ftp_user,
                                          self.ftp_pass, ftp_file_path)
        else:
            self.android_ue._method_proxy('release_downlink_ftp_data_transfer', self.pid, self.ue_local_path)

    def is_running(self):
        """
        Check if data transfer is running
        :return: boolean
        """
        if self.pid is None:
            return False
        if self.android_ue._method_proxy('is_process_finished', self.pid):
            return False
        return True

    def check_data_transfer(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def reset_statistics(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def get_average_throughput(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()

    def get_datagram_loss(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError()


class AndroidDataTransferFtpNaa(LteDataTransfer):
    """Object responsible for managing Android data transfer."""

    # pylint: disable = protected-access, too-many-instance-attributes, duplicate-code
    def __init__(self, name, dt_definition, configuration, android_ue, logger_name='ute_ue'):
        """
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param android_ue:
        """
        super(AndroidDataTransferFtpNaa, self).__init__(name, dt_definition, configuration, logger_name)
        raw_logger = logging.getLogger('ute_ue')
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.android_ue = android_ue
        self.success_started = False
        self.ftp_ip = self._get_ftp_parameter('host_ip')
        self.ftp_user = self._get_ftp_parameter('user')
        self.ftp_pass = self._get_ftp_parameter('password')
        self.ftp_remote_path = self._get_ftp_parameter('remote_path')

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        try:
            if self._is_upload():
                self.ftp_file_size = self._get_ftp_parameter('file_size')
                self.ftp_test_index = self._get_ftp_parameter('test_index')
                self.android_ue._method_proxy('ftp_start_ul', self.ftp_ip, self.ftp_user, self.ftp_pass,
                                              self.ftp_remote_path, self._dt_definition.direction,
                                              self.ftp_file_size, self.ftp_test_index)
            else:
                self.android_ue._method_proxy('ftp_start_dl', self.ftp_ip, self.ftp_user, self.ftp_pass,
                                              self.ftp_remote_path, self._dt_definition.direction)
            if self._get_ftp_result() != 'success':
                self._raise_if_result_not_success()

        except Exception as e:
            self.logger.debug('Something went wrong during {} ftp data transfer start:\n{}'.format(self.name, e))
            raise e

    def get_average_throughput(self):
        """
        Get average throughput of FTP data transfer
        :return:
        """
        return int(self.android_ue._method_proxy('ftp_get_average_throughput'))

    def _get_ftp_parameter(self, param):
        config = self._configuration
        if param in self._dt_definition.protocol_details:
            return self._dt_definition.protocol_details[param]
        if 'data_transfer' in config and 'ftp' in config['data_transfer'] and param in config['data_transfer']['ftp']:
            return config['data_transfer']['ftp'][param]
        return self._raise_if_direction_required_param_missing(param)

    def _raise_if_direction_required_param_missing(self, param):
        direction_required_params = {'dl': ['host_ip', 'user', 'password', 'remote_path'],
                                     'ul': ['host_ip', 'user', 'password', 'remote_path', 'file_size', 'test_index']}
        if param in direction_required_params[self._dt_definition.direction]:
            err_msg = "Please provide {} argument at the end of keyword or in ftp section at yml file.".format(param)
            raise DataTransferMissingArguments(err_msg)

    def _raise_if_result_not_success(self):
        err_msg = "Something went wrong during ftp data transfer. Please check if all parameters provided correctly " \
                  "and transfer between client and server works well manually"
        raise DataTransferVerificationFailure(err_msg)

    def _is_upload(self):
        return self._dt_definition.direction == 'ul'

    def _get_ftp_result(self):
        return self.android_ue._method_proxy('ftp_get_result')
